create table users (id bigint auto_increment primary key, email varchar(190) not null unique, password_hash varchar(255) not null, full_name varchar(120) not null, role varchar(30) not null default 'USER', created_at timestamp not null default current_timestamp);
create table profiles (id bigint auto_increment primary key, user_id bigint not null unique, age integer, height_cm decimal(6,2), weight_kg decimal(6,2), goal varchar(50), experience varchar(50), location varchar(50), equipment varchar(500), diet varchar(80), allergies varchar(500), limitations varchar(1000), onboarding_complete boolean not null default false, constraint fk_profile_user foreign key(user_id) references users(id));
create table readiness_entries (id bigint auto_increment primary key, user_id bigint not null, entry_date date not null, sleep_hours decimal(4,1), sleep_quality integer, energy integer, soreness integer, mood integer, stress integer, available_minutes integer, current_condition varchar(300), resting_heart_rate integer, hrv integer, score integer not null, recommendation varchar(500), constraint fk_readiness_user foreign key(user_id) references users(id));
create table workouts (id bigint auto_increment primary key, user_id bigint not null, title varchar(150) not null, duration_minutes integer not null, intensity varchar(40), location varchar(40), goal varchar(50), status varchar(30), exercises text, feedback varchar(50), started_at timestamp, completed_at timestamp, constraint fk_workout_user foreign key(user_id) references users(id));
create table meals (id bigint auto_increment primary key, user_id bigint not null, name varchar(180) not null, goal varchar(50), ingredients text, instructions text, calories integer, protein_g integer, prep_minutes integer, created_at timestamp not null default current_timestamp, constraint fk_meal_user foreign key(user_id) references users(id));
create table form_sessions (id bigint auto_increment primary key, user_id bigint not null, exercise varchar(100), reps integer, score integer, feedback text, created_at timestamp not null default current_timestamp, constraint fk_form_user foreign key(user_id) references users(id));
create index idx_readiness_user_date on readiness_entries(user_id, entry_date);
create index idx_workout_user on workouts(user_id, completed_at);
